INSERT INTO counties VALUES ('18uk1JWRR4AJkbkWI0rx','Taita-Taveta','006','Known for Tsavo National Parks, wildlife conservation, and scenic Taita Hills.',0,340671,'17,084 km²','Wundanyi','2026-04-16 14:24:48','2026-04-16 14:24:48'),('1vY08vZ2FlxF2Raw0qXc','Kitui','015','Semi-arid county known for livestock keeping, mining, and traditional crafts.',0,1136187,'30,497 km²','Kitui Town','2026-04-16 14:24:54','2026-04-16 14:24:54'),('2D5MXZ7tgITKdtOTxRZQ','Mombasa','001','Coastal city and major port. Famous for beautiful beaches, historical sites like Fort Jesus, and Swahili culture. Tourism hotspot.',1,1208333,'294.7 km²','Mombasa City','2026-04-16 14:24:33','2026-04-16 14:24:33'),('2YMfthQCmJYsAMHj2SQw','Laikipia','031','Wildlife conservation county. Known for private ranches and community conservancies.',0,518560,'9,462 km²','Nanyuki','2026-04-16 14:25:02','2026-04-16 14:25:02'),('3W1vOk05fx9kTwV36okM','Nairobi','047','Capital city and economic hub of Kenya. Known as the \'Green City in the Sun\' with vibrant nightlife, business centers, and diverse entertainment options.',1,4397073,'696 km²','Nairobi City','2026-04-16 14:24:31','2026-04-16 14:24:31'),('4kJDtwAEkHO4D9AO1AvJ','Tharaka-Nithi','013','Agricultural county known for miraa, coffee, and fruit farming along the Tana River.',0,393177,'2,609 km²','Kathwana','2026-04-16 14:24:52','2026-04-16 14:24:52'),('5gimsvZ0RWH1D0vKSbxp','Kirinyaga','020','County on the slopes of Mount Kenya. Known for rice farming in Mwea and coffee production.',0,610411,'1,478 km²','Kerugoya','2026-04-16 14:24:56','2026-04-16 14:24:56'),('6tass42O6SpWXk0oboeA','Vihiga','038','Smallest county in Kenya. Known for sugarcane farming and Luhya cultural heritage.',0,590013,'531 km²','Vihiga Town','2026-04-16 14:25:04','2026-04-16 14:25:04'),('87yxYJ4a1jtpoDkvaOJO','Homa Bay','043','County on Lake Victoria shores. Known for fishing industry and Ruma National Park.',0,1131950,'3,183 km²','Homa Bay Town','2026-04-16 14:25:06','2026-04-16 14:25:06')